-- quest_extra.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[9257] = {id=9257,name="Atiesh, Greatstaff of the Guardian",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="This final task will be the most difficult of all, . You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras. Take the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.",objectivesText="Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.",starts={{npcID=15192}},questType="dungeon"},
[9266] = {id=9266,name="Making Amends",level=1,requiredLevel=1,faction="both",expansion=2,zoneID=618,mapID=83,objectivesText="Progress: You must've done something really bad to us or our friends, <name>. At any rate, I'm here to offer you a way to get our good graces back. As you know, Winterspring is quite cold. With so many of us goblins coming from other cities, we could use a hand keeping warm. Bring me some runecloth and coal and I'll put in the good word for ya. Be warned though, our enemies are not going to take kindly to your helping us.",starts={{npcID=16416,x=0.58,y=0.522,zoneID=618}},ends={{npcID=16416,x=0.58,y=0.522,zoneID=618}},coords={x=0.58,y=0.522,source="quest_giver",zoneID=618},questType="standard"},
[9269] = {id=9269,name="Atiesh, Greatstaff of the Guardian",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="This final task will be the most difficult of all, . You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras. Take the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.",objectivesText="Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.",starts={{npcID=15192}},questType="dungeon"},
[9270] = {id=9270,name="Atiesh, Greatstaff of the Guardian",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="This final task will be the most difficult of all, . You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras. Take the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.",objectivesText="Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.",starts={{npcID=15192}},questType="dungeon"},
[9271] = {id=9271,name="Atiesh, Greatstaff of the Guardian",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="This final task will be the most difficult of all, . You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras. Take the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.",objectivesText="Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.",starts={{npcID=15192}},questType="dungeon"},
[9287] = {id=9287,name="Paladin Training",level=5,requiredLevel=5,faction="alliance",expansion=2,starts={{x=0.512,y=0.412,mapID=468,npcID=16501}},ends={{x=0.512,y=0.412,mapID=468,npcID=16501}},coords={mapID=468,x=0.512,y=0.412},questType="standard"},
[9288] = {id=9288,name="Hunter Training",level=5,requiredLevel=5,faction="alliance",expansion=2,starts={{x=0.516,y=0.442,mapID=468,npcID=16499}},ends={{x=0.516,y=0.442,mapID=468,npcID=16499}},coords={mapID=468,x=0.516,y=0.442},questType="standard"},
[9289] = {id=9289,name="Warrior Training",level=5,requiredLevel=5,faction="alliance",expansion=2,starts={{x=0.51,y=0.438,mapID=468,npcID=16503}},ends={{x=0.51,y=0.438,mapID=468,npcID=16503}},coords={mapID=468,x=0.51,y=0.438},questType="standard"},
[9436] = {id=9436,name="Bloodscalp Insight",level=10,requiredLevel=10,faction="horde",expansion=2,zoneID=33,mapID=50,description="Well met, <class>. I've made a habit of studying the fighting techniques of the various troll tribes in my travels, and I've noticed a trend. The Bloodscalp trolls at the Tkashi Ruins and Bal'lal Ruins to the north use some of the same tactics as the Amani of the northern forests. Their magic seems to have diverged in an interesting direction and they've used it to become the strongest tribe in the area. It could form the core of a powerful weapon against the Amani, but first I must find out more about it.",objectivesText="Nemeth Hawkeye at Grom'gol Base Camp wants you to bring him a Bloodscalp Totem from a Bloodscalp Shaman. Progress: Do not fail me, <name>. If we can bend this Bloodscalp magic to our will, my people may yet eliminate the Amani threat.",starts={{mapID=50,npcID=17094,x=0.38,y=0.502}},ends={{mapID=50,npcID=17094,x=0.38,y=0.502}},coords={mapID=50,source="quest_giver",x=0.38,y=0.502},questType="standard"},
[9437] = {id=9437,name="Twilight of the Dawn Runner",level=15,requiredLevel=15,faction="horde",expansion=2,zoneID=15,mapID=70,description="The ogres here are useful for little more than crude jokes, sour ale, and bouts of headbutting. When my ship, the Dawn Runner, ran aground, those curs from Theramore made off with my cargo and last surviving crewman. I made my way here searching for help, but those good-for-nothing ogres stared blankly at me when I told them my story. I could use the help of a reliable in recovering what remains of my cargo and freeing Ithania from North Point Tower, to the northeast, where they're being held.",objectivesText="Balandar Brightstar in Brackenwall Village wants you to reclaim the Dawn Runner Cargo and rescue his first mate Ithania from forces of Theramore at North Point Tower. Progress: Have you freed Ithania and reclaimed my cargo from those glorified privateers?",starts={{npcID=17095,x=0.358,y=0.316,zoneID=15}},ends={{npcID=17095,x=0.358,y=0.316,zoneID=15}},coords={x=0.358,y=0.316,source="quest_giver",zoneID=15},questType="standard"},
[9457] = {id=9457,name="An Unusual Patron",level=10,requiredLevel=10,faction="horde",expansion=2,zoneID=33,mapID=50,description="So this Naias is the mastermind behind the Bloodscalp and their exotic magic? I'll admit, this is the last place I expected my inquiry to lead, but no matter, our findings may still prove useful. Off the coast to the northwest is an island inhabited by lesser water elementals. There's a crude stone slab there that might serve as an altar for the likes of the trolls. Take the totem you found to that altar. Let's see if we can draw this Naias out and distill his power into a more agreeable form.",objectivesText="Use the Gift of Naias near the Altar of Naias to summon the water elemental Naias. Defeat him and return to Nemeth Hawkeye at Grom'gol Base Camp with the Heart of Naias . Progress: What news of Naias, <name>?",starts={{mapID=50,npcID=17094,x=0.38,y=0.502}},ends={{mapID=50,npcID=17094,x=0.38,y=0.502}},coords={mapID=50,source="quest_giver",x=0.38,y=0.502},questType="standard"},
[9626] = {id=9626,name="Meeting the Orcs",level=1,requiredLevel=1,faction="horde",expansion=2,zoneID=1637,mapID=90,description="I haven't lost any love for my homeland or its people, as you know. I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table. This should silence any opposition. Take this letter to Saurfang in Orgrimmar . As leader of the orcs, he must have a say in accepting the sin'dorei's pledge. I've added my own seal to the letter as a personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the tower.",objectivesText="Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to High Overlord Saurfang in Orgrimmar , capital of Durotar. Progress: You've come to see me, <race>? Speak and be quick, young lady. I've no time for the formalities of your race.",starts={{npcID=10181,x=0.578,y=0.916,zoneID=1497}},ends={{npcID=14720,x=0.486,y=0.71,zoneID=1637},{npcID=39605,x=0.482,y=0.706,zoneID=1637},{npcID=86832,x=0.482,y=0.706,zoneID=1637}},coords={x=0.578,y=0.916,source="quest_giver",zoneID=1497},questType="standard"},
[9627] = {id=9627,name="Allegiance to the Horde",level=1,requiredLevel=1,faction="horde",expansion=2,zoneID=3487,mapID=85,description="Your people suffered a great betrayal by the Alliance. You succeeded in fighting off the Darnassian attacks and the spies from Ironforge. Now you defeated a powerful Scourge leader at the footsteps of your home. Your worthiness is no longer in question. It is clear now that we need each other. Return to Lor'themar. Tell him I have heard your message and accept. Welcome to the Horde, elf.",objectivesText="Return to Silvermoon City and report back to Lor'themar Theron .",starts={{npcID=14720,x=0.486,y=0.71,zoneID=1637},{npcID=39605,x=0.482,y=0.706,zoneID=1637}},ends={{npcID=16802,x=0.54,y=0.204,zoneID=3487}},coords={x=0.486,y=0.71,source="quest_giver",zoneID=1637},questType="standard"},
[9813] = {id=9813,name="Meeting the Orcs",level=1,requiredLevel=1,faction="horde",expansion=2,zoneID=1637,mapID=90,description="I haven't lost any love for my homeland or its people, as you know. I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table. This should silence any opposition. Take this letter to Saurfang in Orgrimmar . As leader of the orcs, he must have a say in accepting the sin'dorei's pledge. I've added my own seal to the letter as a personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the tower.",objectivesText="Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to High Overlord Saurfang in Orgrimmar , capital of Durotar. Progress: Yes, <class>?",starts={{npcID=10181,x=0.578,y=0.916,zoneID=1497}},ends={{npcID=14720,x=0.486,y=0.71,zoneID=1637},{npcID=39605,x=0.482,y=0.706,zoneID=1637},{npcID=86832,x=0.482,y=0.706,zoneID=1637}},coords={x=0.578,y=0.916,source="quest_giver",zoneID=1497},questType="standard"},
[10277] = {id=10277,name="The Caverns of Time",level=15,requiredLevel=15,faction="both",expansion=2,zoneID=440,description="Greetings, . Please follow the custodian. She will make things a bit more... clear.",objectivesText="Andormu at the Caverns of Time has asked that you follow the Custodian of Time around the cavern. Progress: Do not return until you have at least a rudimentary understanding of what is happening.",starts={{x=0.415,y=0.385,mapID=75,npcID=20130}},ends={{x=0.415,y=0.385,mapID=75,npcID=20130}},coords={mapID=75,x=0.415,y=0.385},questType="standard"},
[10279] = {id=10279,name="To The Master's Lair",level=15,requiredLevel=15,faction="both",expansion=2,zoneID=440,description="Ah, . We have been expecting you. Please, allow one of my brothers to fly you down to the master. He awaits you below...",objectivesText="Speak to Andormu at the Caverns of Time.",starts={{x=0.553,y=0.279,mapID=74,npcID=20142}},ends={{x=0.553,y=0.279,mapID=74,npcID=20142}},coords={mapID=74,x=0.553,y=0.279},questType="standard"},
[10282] = {id=10282,name="Old Hillsbrad",level=15,requiredLevel=15,faction="both",expansion=2,zoneID=2367,description="To the west is the timeway to Hillsbrad of the past - 7 years to be exact. Forces are working against the Horde warchief, Thrall, attempting to prevent him from ever escaping Durnholde Keep. If Thrall never escapes, this world - as you know it - will cease to exist. Gather a group of adventurers and take the timeway to old Hillsbrad. Two of our agents await you inside. Speak with Erozion on the other side.",objectivesText="Andormu at the Caverns of Time has asked that you venture to Old Hillsbrad and speak with Erozion .",starts={{x=0.416,y=0.385,mapID=75,npcID=20130}},ends={{npcID=18723,x=0.288,y=0.482,zoneID=2367}},coords={mapID=75,x=0.416,y=0.385},questType="dungeon"},
[10297] = {id=10297,name="The Opening of the Dark Portal",level=25,requiredLevel=25,faction="both",expansion=2,zoneID=2366,description="Beyond this timeway the Guardian, Medivh, feverishly works to open the Dark Portal. Scattered across the morass, rifts will materialize. Infinite will pour out of the rifts and attempt to destroy Medivh's shields and, ultimately, Medivh. Kill their rift lords and leaders! Do this until Medivh succeeds.",objectivesText="Sa'at inside the Black Morass of the Caverns of Time has tasked you with defending Medivh until he succeeds in opening the Dark Portal. Return to Sa'at should you succeed in your task. Progress: Use your chrono-beacon if you require aid. You may only use one chrono-beacon per pocket of time.",starts={{npcID=20201}},questType="dungeon"},
[10460] = {id=10460,name="Defender's Pledge",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,mapID=71,starts={{npcID=19935}},questType="standard"},
