[10464] = {id=10464,name="Sage's Vow",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="You've made your pledge, . Now it is up to you to see it through. Serve the Scale of the Sands well and you will be rewarded. Fail and the timeline as we know it will be unravelled!",objectivesText="Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Honored reputation with the Scale of the Sands . Progress: You continue to serve us well, <name>.",starts={{npcID=19935}},questType="standard"},
