[10468] = {id=10468,name="Sage's Oath",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="You've carried out the promise you made to us, . And for that you've gained the recognition you deserve. As you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring. It won't be long until it has reached its full potential.",objectivesText="Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands . Progress: You've returned. You wish to speak to me?",starts={{npcID=19935}},questType="standard"},
[10469] = {id=10469,name="Restorer's Oath",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="You've carried out the promise you made to us, . And for that you've gained the recognition you deserve. As you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring. It won't be long until it has reached its full potential.",objectivesText="Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands . Progress: You've returned. You wish to speak to me?",starts={{npcID=19935}},questType="standard"},
[10470] = {id=10470,name="Champion's Oath",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="You've carried out the promise you made to us, . And for that you've gained the recognition you deserve. As you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring. It won't be long until it has reached its full potential.",objectivesText="Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands . Progress: You've returned. You wish to speak to me?",starts={{npcID=19935}},questType="standard"},
[10471] = {id=10471,name="Defender's Oath",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="You've carried out the promise you made to us, . And for that you've gained the recognition you deserve. As you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring. It won't be long until it has reached its full potential.",objectivesText="Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands . Progress: You've returned. You wish to speak to me?",starts={{npcID=19935}},questType="standard"},
[10472] = {id=10472,name="Sage's Covenant",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="Your accomplishments have gone beyond my greatest expectations, . You step in and out of time as comfortably as any bronze dragon I've known. You are destined for great power and I am more than pleased to help you on your way there. Continue to serve the Scale of the Sands and I will unleash your gift's full potential.",objectivesText="Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands . Progress: May time always be on your side, <name>.",starts={{npcID=19935}},questType="standard"},
[10473] = {id=10473,name="Restorer's Covenant",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=440,description="Your accomplishments have gone beyond my greatest expectations, . You step in and out of time as comfortably as any bronze dragon I've known. You are destined for great power and I am more than pleased to help you on your way there. Continue to serve the Scale of the Sands and I will unleash your gift's full potential.",objectivesText="Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands . Progress: May time always be on your side, <name>.",starts={{npcID=19935}},questType="standard"},
