[13479] = {id=13479,name="The Great Egg Hunt",level=1,requiredLevel=1,faction="horde",expansion=2,zoneID=15969,mapID=1,description="Noblegarden, celebration of life and spring! I hope you've been enjoying the egg hunt, friend, because I could use the services of a capable individual like you. I'm not certain what form of magic was used in the creation of the eggs, and the druids aren't keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.",objectivesText="Get 20 shell fragments. Progress: Do you have the fragments?",starts={{npcID=32798,x=0.518,y=0.42,zoneID=14},{npcID=32798,x=0.616,y=0.53,zoneID=85},{npcID=32798,x=0.47,y=0.594,zoneID=215},{npcID=32798,x=0.476,y=0.47,zoneID=3430},{npcID=215033,x=0.542,y=0.6,zoneID=13862},{npcID=215033,x=0.46,y=0.548,zoneID=14771},{npcID=215033,x=0.512,y=0.762,zoneID=15969}},ends={{npcID=32798,x=0.518,y=0.42,zoneID=14},{npcID=32798,x=0.616,y=0.53,zoneID=85},{npcID=32798,x=0.47,y=0.594,zoneID=215},{npcID=32798,x=0.476,y=0.47,zoneID=3430},{npcID=215033,x=0.542,y=0.6,zoneID=13862},{npcID=215033,x=0.46,y=0.548,zoneID=14771},{npcID=215033,x=0.512,y=0.762,zoneID=15969}},coords={x=0.518,y=0.42,source="quest_giver",zoneID=14},questType="standard"},
[13480] = {id=13480,name="The Great Egg Hunt",level=1,requiredLevel=1,faction="alliance",expansion=2,zoneID=15969,mapID=27,description="Noblegarden, celebration of life and spring! I hope you've been enjoying the egg hunt, friend, because I could use the services of a capable individual like you. I'm not certain what form of magic was used in the creation of the eggs, and the druids aren't keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.",objectivesText="Get 20 shell fragments. Progress: Do you have the fragments?",starts={{npcID=32799,x=0.54,y=0.508,zoneID=1},{npcID=32799,x=0.426,y=0.658,zoneID=12},{npcID=32799,x=0.556,y=0.512,zoneID=141},{npcID=32799,x=0.49,y=0.512,zoneID=3524},{npcID=215033,x=0.542,y=0.6,zoneID=13862},{npcID=215033,x=0.46,y=0.548,zoneID=14771},{npcID=215033,x=0.512,y=0.762,zoneID=15969}},ends={{npcID=32799,x=0.54,y=0.508,zoneID=1},{npcID=32799,x=0.426,y=0.658,zoneID=12},{npcID=32799,x=0.556,y=0.512,zoneID=141},{npcID=32799,x=0.49,y=0.512,zoneID=3524},{npcID=215033,x=0.542,y=0.6,zoneID=13862},{npcID=215033,x=0.46,y=0.548,zoneID=14771},{npcID=215033,x=0.512,y=0.762,zoneID=15969}},coords={x=0.54,y=0.508,source="quest_giver",zoneID=1},questType="standard"},
[13481] = {id=13481,name="Let's Get Out of Here!",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape. I cannot make it on my own, , but with your help, I may yet live to fight the Scourge again. Will you help me make my escape before the Scourge's butchers come to finish me off?",objectivesText="Escort Father Kamaros to safety and then report to Brother Keltan aboard Orgrim's Hammer.",starts={{npcID=32800,x=0.318,y=0.648,zoneID=210}},ends={{npcID=31261,x=0.694,y=0.424,zoneID=210}},coords={x=0.318,y=0.648,source="quest_giver",zoneID=210},questType="standard"},
[13482] = {id=13482,name="Let's Get Out of Here",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape. I cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again. Will you help me make my escape before the Scourge's butchers come to finish me off?",objectivesText="Escort Father Kamaros to safety and then report to Absalan the Pious aboard the Skybreaker.",starts={{npcID=32800,x=0.318,y=0.648,zoneID=210}},ends={{npcID=31259,x=0.592,y=0.484,zoneID=210}},coords={x=0.318,y=0.648,source="quest_giver",zoneID=210},questType="standard"},
[13501] = {id=13501,name="Candy Bucket",level=10,requiredLevel=10,faction="horde",expansion=2,zoneID=3537,mapID=114,starts={{npcID=194084,x=0.497,y=0.1,mapID=114}},ends={{npcID=194084,x=0.497,y=0.1,mapID=114}},coords={x=0.497,y=0.1,source="quest_giver",mapID=114},questType="standard"},
[13502] = {id=13502,name="A Tisket, a Tasket, a Noblegarden Basket",level=1,requiredLevel=1,faction="alliance",expansion=2,zoneID=15969,mapID=27,description="Here... take this egg basket and go hunting for brightly colored eggs. Return to me with the basket when you've found ten Noblegarden chocolates , please.",objectivesText="Collect 10 Noblegarden Chocolates and return them along with the Borrowed Egg Basket . Progress: Do you have the ten Noblegarden Chocolates ?",starts={{npcID=32836,x=0.54,y=0.508,zoneID=1},{npcID=32836,x=0.426,y=0.658,zoneID=12},{npcID=32836,x=0.556,y=0.512,zoneID=141},{npcID=32836,x=0.49,y=0.512,zoneID=3524},{npcID=215033,x=0.542,y=0.6,zoneID=13862},{npcID=215033,x=0.46,y=0.548,zoneID=14771},{npcID=215033,x=0.512,y=0.762,zoneID=15969}},ends={{npcID=32836,x=0.54,y=0.508,zoneID=1},{npcID=32836,x=0.426,y=0.658,zoneID=12},{npcID=32836,x=0.556,y=0.512,zoneID=141},{npcID=32836,x=0.49,y=0.512,zoneID=3524},{npcID=215033,x=0.542,y=0.6,zoneID=13862},{npcID=215033,x=0.46,y=0.548,zoneID=14771},{npcID=215033,x=0.512,y=0.762,zoneID=15969}},coords={x=0.54,y=0.508,source="quest_giver",zoneID=1},questType="standard"},
[13503] = {id=13503,name="A Tisket, a Tasket, a Noblegarden Basket",level=1,requiredLevel=1,faction="horde",expansion=2,zoneID=15969,mapID=1,description="Here--take this egg basket and go hunting for brightly colored eggs. Return to me with the basket when you've found ten Noblegarden chocolates .",objectivesText="Collect 10 Noblegarden Chocolates and return them along with the Borrowed Egg Basket . Progress: Do you have the ten Noblegarden Chocolates ?",starts={{npcID=32837,x=0.522,y=0.416,zoneID=14},{npcID=32837,x=0.614,y=0.53,zoneID=85},{npcID=32837,x=0.47,y=0.598,zoneID=215},{npcID=32837,x=0.476,y=0.472,zoneID=3430},{npcID=215033,x=0.542,y=0.6,zoneID=13862},{npcID=215033,x=0.46,y=0.548,zoneID=14771},{npcID=215033,x=0.512,y=0.762,zoneID=15969}},ends={{npcID=32837,x=0.522,y=0.416,zoneID=14},{npcID=32837,x=0.614,y=0.53,zoneID=85},{npcID=32837,x=0.47,y=0.598,zoneID=215},{npcID=32837,x=0.476,y=0.472,zoneID=3430},{npcID=215033,x=0.542,y=0.6,zoneID=13862},{npcID=215033,x=0.46,y=0.548,zoneID=14771},{npcID=215033,x=0.512,y=0.762,zoneID=15969}},coords={x=0.522,y=0.416,source="quest_giver",zoneID=14},questType="standard"},
[13538] = {id=13538,name="Southern Sabotage",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=4197,mapID=123,description="The three towers south of the Wintergrasp river are draining power from the Fortress! Destroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower, then return to me. Remember, only siege vehicles can damage a tower, so make sure to protect them from the Horde!",objectivesText="Destroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower and return to Tactical Officer Ahbramis in Wintergrasp .",starts={{npcID=31153,x=0.502,y=0.178,zoneID=4197}},ends={{npcID=31153,x=0.502,y=0.178,zoneID=4197}},coords={x=0.502,y=0.178,source="quest_giver",zoneID=4197},questType="pvp"},
[13539] = {id=13539,name="Toppling the Towers",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=4197,mapID=123,description="While the Alliance may be pounding on our doors, a true tactician looks beyond the obvious. \"Attack him where he is unprepared, appear where you are not expected.\" , I need you to travel across the Wintergrasp River and destroy one of the three towers to the south. Our Warlocks report that the towers are draining power we could use to bolster our own troops. Return to me once you've destroyed a tower.",objectivesText="Destroy Shadowsight Tower, Flamewatch Tower, or Winter's Edge Tower and return to Tactical Officer Kilrath in Wintergrasp .",starts={{npcID=31151,x=0.502,y=0.178,zoneID=4197}},ends={{npcID=31151,x=0.502,y=0.178,zoneID=4197}},coords={x=0.502,y=0.178,source="quest_giver",zoneID=4197},questType="pvp"},
[13548] = {id=13548,name="Candy Bucket",level=10,requiredLevel=10,faction="horde",expansion=2,zoneID=67,mapID=120,starts={{npcID=194119,x=0.371,y=0.496,mapID=120}},ends={{npcID=194119,x=0.371,y=0.496,mapID=120}},coords={x=0.371,y=0.496,source="quest_giver",mapID=120},questType="standard"},
[13549] = {id=13549,name="Tails Up",level=20,requiredLevel=20,faction="both",expansion=2,zoneID=66,mapID=121,description="Along with the Drakkari artifacts, I'm interested in returning to Zandalar with some of the Zul'Drak wildlife. I have males of both the frost leopards and icepaw bears, but I need females! Too bad that my trapper was killed in a most unfortunate accident. Perhaps you would be willing to fill in for him? Put the leopards and bears to sleep with this blowgun then lift their tails and return with some females if you would be so kind. They can be found near the Altars of Rhunok, Quetz'lun, and Har'koa.",objectivesText="Chronicler To'kini at Zim'Torga wants you to use To'kini's Blowgun on Frost Leopards and Icepaw Bears. Return to him with 3 females of each.",starts={{npcID=28527,x=0.598,y=0.578,zoneID=66}},ends={{npcID=28527,x=0.598,y=0.578,zoneID=66}},coords={x=0.598,y=0.578,source="quest_giver",zoneID=66},questType="standard"},
[13556] = {id=13556,name="Eggs for Dubra'Jin",level=20,requiredLevel=20,faction="both",expansion=2,zoneID=66,mapID=121,description="How ya doin', mon? Thinkin' ya might be helpin' me out? Bah'Kini be needin' lots o' the raptor eggs to be sacrificin' to Dubra'Jin. How ya thinkin' we not be overrun yet by the Drakkari? Dubra'Jin be lendin' us his aid! We need ya to gather up the raptor eggs from around the trees outside here in Gundrak. Sometimes the raptors carry 'em to keep 'em warm, too.",objectivesText="Ha'wana at Dubra'Jin needs you to collect 12 Gundrak Raptor Eggs . Progress: Who woulda thought the great Dubra'Jin be wantin' so many eggs? What he gonna do with them anyway?",starts={{npcID=33025,x=0.7,y=0.21,zoneID=66}},ends={{npcID=33025,x=0.7,y=0.21,zoneID=66}},coords={x=0.7,y=0.21,source="quest_giver",zoneID=66},questType="standard"},
[13559] = {id=13559,name="Hodir's Tribute",level=25,requiredLevel=25,faction="both",expansion=2,zoneID=67,mapID=120,objectivesText="Progress: No ordinary tributes were good enough for the great Hodir when he walked among the frost giants. He might not be with us anymore, but we've kept the tradition of offering tribute to his strength and wisdom. It would do much for your renown to partake in this tradition, small <class>.",starts={{npcID=32540,x=0.66,y=0.614,zoneID=67}},ends={{npcID=32540,x=0.66,y=0.614,zoneID=67}},coords={x=0.66,y=0.614,source="quest_giver",zoneID=67},questType="standard"},
[13571] = {id=13571,name="Fletcher's Lost and Found",level=10,requiredLevel=10,faction="both",expansion=2,zoneID=4395,mapID=118,starts={{x=0.442,y=0.256,mapID=126,npcID=32516}},ends={{x=0.442,y=0.256,mapID=126,npcID=32516}},coords={mapID=126,x=0.442,y=0.256},questType="standard"},
[13592] = {id=13592,name="A Valiant's Field Training",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy. Travel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.",objectivesText="Sir Marcus Barlowe at the Argent Tournament Grounds wants you to kill 10 Converted Heroes . Progress: Have you tested yourself in combat against the Scourge?",starts={{npcID=33222,x=0.764,y=0.192,zoneID=210}},ends={{npcID=33222,x=0.764,y=0.192,zoneID=210}},coords={x=0.764,y=0.192,source="quest_giver",zoneID=210},questType="standard"},
[13593] = {id=13593,name="Valiant Of Stormwind",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Stormwind's tournament delegation? You will train and rise through the ranks as you have before, but when you are named a champion of Stormwind, your squire will have the option of carrying our banner into battle.",objectivesText="Speak with Marshal Jacob Alerius again if you wish to become a valiant of Stormwind.",starts={{npcID=33225,x=0.766,y=0.192,zoneID=210}},ends={{npcID=33225,x=0.766,y=0.192,zoneID=210}},coords={x=0.766,y=0.192,source="quest_giver",zoneID=210},questType="standard"},
[13600] = {id=13600,name="A Worthy Weapon",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Of all the times to have such rotten luck! My tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.",objectivesText="Bring the Blade of Drak'Mar to Marshal Jacob Alerius at the Argent Tournament Grounds. Progress: Were the wandering bard's tales true? Have you brought a blade?",starts={{npcID=33225,x=0.766,y=0.192,zoneID=210}},ends={{npcID=33225,x=0.766,y=0.192,zoneID=210}},coords={x=0.766,y=0.192,source="quest_giver",zoneID=210},questType="standard"},
[13603] = {id=13603,name="A Blade Fit For A Champion",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, . Otherwise, you'll catch warts.",objectivesText="Retrieve the Ashwood Brand and bring it to Marshal Jacob Alerius at the Argent Tournament Grounds. Progress: Were you able to recover the blade?",starts={{npcID=33225,x=0.766,y=0.192,zoneID=210}},ends={{npcID=33225,x=0.766,y=0.192,zoneID=210}},coords={x=0.766,y=0.192,source="quest_giver",zoneID=210},questType="standard"},
[13604] = {id=13604,name="Archivum Data Disc",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,mapID=114,description="This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections. Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\" There must be a device inside Ulduar capable of reading the disc.",objectivesText="Bring the Archivum Data Disc to the Archivum Console in Ulduar . Progress: The console whirrs with energy as the round receptacle opens.",ends={{npcID=194555,mapID=114},{npcID=194555,mapID=114}},questType="raid"},
[13606] = {id=13606,name="Freya's Sigil",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,description="Freya's Sigil is going to be one of the tougher ones, I reckon. According to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark. Should any of the elders be harmed, the Sigil's integrity will be compromised. Sparing the elders, however, means that Freya will be more powerful when you face her. What can I say, . We're stuck between a rock and hard place.",objectivesText="Prospector Doren at the Archivum in Ulduar wants you to obtain Freya's Sigil . For more information on obtaining Freya's Sigil consult the Archivum Console. Progress: Freya's sigil , <name>? Do ye have it?",starts={{npcID=33957}},questType="raid"},
[13607] = {id=13607,name="The Celestial Planetarium",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,description="Listen, ! Azeroth's fate is at stake here. Our only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters. Locate the Celestial Planetarium and come back with any information you get. We might still have some time to prepare for Algalon's arrival.",objectivesText="Prospector Doren at the Archivum in Ulduar wants you to locate the entrance to the Celestial Planetarium.",starts={{npcID=33957}},questType="raid"},
[13609] = {id=13609,name="Hodir's Sigil",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,description="Hodir's Sigil won't be easy to obtain. Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it! Check the Archivum console if you need more information. That thing contains more knowledge than all of the world's libraries put together!",objectivesText="Prospector Doren at the Archivum in Ulduar wants you to obtain Hodir's Sigil . For more information on obtaining Hodir's Sigil , consult the Archivum Console. Progress: Did ye obtain the sigil, <name>?",starts={{npcID=33957}},questType="raid"},
[13610] = {id=13610,name="Thorim's Sigil",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,description="Thorim's not himself, . He's come under a dark influence. An evil presence under the guise of an illusion pretends to be his lost wife, Sif. Ye can't let him be overcome by this impostor's spell. If he does, the location of his sigil might forever be lost! Yer going to have to beat some sense into him and yer going to have to do it quick. As always, the Archivum Console will give ye all the gory details... even the ones ye don't like.",objectivesText="Prospector Doren at the Archivum in Ulduar wants you to obtain Thorim's Sigil . For more information on obtaining Thorim's Sigil consult the Archivum Console. Progress: Well, <name>? Do ye have it?",starts={{npcID=33957}},questType="raid"},
[13611] = {id=13611,name="Mimiron's Sigil",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,description="Mimiron's a clever one. His entire abode is rigged with some sort of self-destruction mechanism. Unfortunately yer gonna have to race against it if ye want to get his sigil. Check the Archivum Console for more details if ye need them.",objectivesText="Prospector Doren at the Ulduar Archivum wants you to obtain Mimiron's Sigil . For more information on obtaining Mimiron's Sigil consult the Archivum Console. Progress: Were you able to obtain the sigil, <name>?",starts={{npcID=33957}},questType="raid"},
[13614] = {id=13614,name="Algalon",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,description="You really did it, . Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium. You best hurry, . Time is of the essence.",objectivesText="Bring the Sigils of the Watchers to the Archivum Console in Ulduar . Progress: The console's bright lights scan the glass surface repeatedly, as if awaiting some form of input.",starts={{npcID=33957}},questType="raid"},
[13616] = {id=13616,name="The Edge Of Winter",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=2817,mapID=118,description="Curse that death knight for breaking my sword! In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, .",objectivesText="Marshal Jacob Alerius at the Argent Tournament Grounds wants you to bring him Winter's Edge . Progress: Did you win the blade I seek?",starts={{npcID=33225,x=0.766,y=0.192,zoneID=210}},ends={{npcID=33225,x=0.766,y=0.192,zoneID=210}},coords={x=0.766,y=0.192,source="quest_giver",zoneID=210},questType="standard"},
[13622] = {id=13622,name="Ancient History",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,mapID=114,description="The pieces fit together to form an elegant hammer. Its construction appears to be at least partially Titan in nature. The console inside the Archivum might have some information regarding this artifact.",objectivesText="Bring the Shattered Fragments of Val'anyr to the Archivum Console in the Archivum in Ulduar . Progress: Awaiting input.",ends={{npcID=194555,mapID=114},{npcID=194555,mapID=114}},questType="raid"},
[13625] = {id=13625,name="Learning The Reins",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds. Visit the stables outside the pavilion, equip your lance, and mount up on the Quel'dorei steed. Familiarize yourself with the tactics available to you and use them to defeat the three different kinds of training dummies.",objectivesText="Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets and then return to Scout Shalyndria at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or the Silver Covenant Pavilion. Progress: How goes the mounted combat practice?",starts={{npcID=33647,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33647,x=0.764,y=0.194,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13627] = {id=13627,name="Jack Me Some Lumber",level=25,requiredLevel=25,faction="none",expansion=2,description="Come closer. No, not too close. Don't want any unnecessary suspicion now, do we? This coliseum requires more lumber than we've stockpiled and there's no way I'm going to pay to have it shipped in from Grizzly Hills. At the western end of Crystalsong Forest, by the Great Tree, grow a number of young Crystalsong oaks. They'd provide just the kind of planking we need for building and scaffolding. Take this axe, use it to fell the trees and then hew them into planks, but don't let anyone see you!",objectivesText="Bring 12 Rough Hewn Planks to Bezzle Blastbolt at the Argent Tournament Grounds.",starts={{x=0.742,y=0.246,mapID=118,npcID=33434}},ends={{x=0.742,y=0.246,mapID=118,npcID=33434}},coords={mapID=118,x=0.742,y=0.246},questType="standard"},
[13629] = {id=13629,name="Val'anyr, Hammer of Ancient Kings",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,description="The Archivum Console has hinted at a possible way to rebind the fragments of Val'anyr: you must get the fragments inside the physical form of the being known as Yogg-Saron. It sounds like a long shot, but for an artifact of such power you think the risk might just be worth it.",objectivesText="Throw the Shattered Pieces of Val'anyr into Yogg-Saron's maw while he's casting Deafening Roar and defeat Yogg-Saron and recover the Reforged Hammer of Ancient Kings . This can only be completed in Heroic mode and only if at least one Ulduar Watcher is not assisting you. Progress: Awaiting input.",starts={{npcID=194555,zoneID=4273},{npcID=194555,zoneID=4273}},ends={{npcID=194555,zoneID=4273},{npcID=194555,zoneID=4273}},questType="raid"},
[13631] = {id=13631,name="All Is Well That Ends Well",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4273,description="We'd best hurry now, . We're going to have to transmit the reply-code from Dalaran. Take it to Rhonin , I will meet you there.",objectivesText="Take the Reply-Code Alpha to Rhonin in Dalaran. Progress: You're ready, <name>?",starts={{npcID=16128}},questType="raid"},
[13633] = {id=13633,name="The Black Knight of Westfall?",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end. Of course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background. He claims to be descended from the Cooper family of Westfall. Would you visit their residence in the western part of Moonbrook in Westfall? See if you can find any proof of his story.",objectivesText="Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings. Progress: Have you found anything related to the Black Knight's story?",starts={{npcID=33417,x=0.694,y=0.23,zoneID=210}},ends={{npcID=33417,x=0.694,y=0.23,zoneID=210}},coords={x=0.694,y=0.23,source="quest_giver",zoneID=210},questType="standard"},
[13634] = {id=13634,name="The Black Knight of Silverpine?",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end. Of course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background. He claims to hail from Valgan's Field in Silverpine Forest. It's a small farm on the western shore of Lordamere Lake. Would you visit the farm and let me know if there's any truth to his story?",objectivesText="Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings. Progress: Have you found anything related to the Black Knight's story?",starts={{npcID=33417,x=0.694,y=0.23,zoneID=210}},ends={{npcID=33417,x=0.694,y=0.23,zoneID=210}},coords={x=0.694,y=0.23,source="quest_giver",zoneID=210},questType="standard"},
[13641] = {id=13641,name="The Seer's Crystal",level=25,requiredLevel=25,faction="both",expansion=2,zoneID=4395,mapID=118,description="Now that we know there's no truth to the Black Knight's stories, we must find a way to connect him to the murdered knights. I know a way to reveal the truth about how they died, but it requires a rare material. We must gain a seer's crystal , found only among the unbound seers who congregate near night elf ruins in the Forlorn Woods in the central part of Crystalsong Forest. Find one of these seers, , and bring me the crystal it holds.",objectivesText="Bring a Seer's Crystal to Crusader Rhydalla at the Argent Tournament Grounds. Progress: Have you located a seer's crystal ?",starts={{npcID=33417,x=0.694,y=0.23,zoneID=210}},ends={{npcID=33417,x=0.694,y=0.23,zoneID=210}},coords={x=0.694,y=0.23,source="quest_giver",zoneID=210},questType="standard"},
[13643] = {id=13643,name="The Stories Dead Men Tell",level=25,requiredLevel=25,faction="both",expansion=2,zoneID=210,mapID=118,description="The crystal will reveal the truth about how three of the tournament's combatants died. Take it with you to the graveyard east of the Tournament Grounds and use it before the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip. If indeed these men were murdered, then we must find a way to tie it to the Black Knight before he strikes again. Look closely at what the crystal tells you, , for we must be certain these deaths were not accidental.",objectivesText="Use the Seer's Crystal at the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip to determine how they died, then return to Crusader Rhydalla . Progress: Have you visisted the graves of the slain combatants?",starts={{npcID=33417,x=0.694,y=0.23,zoneID=210}},ends={{npcID=33417,x=0.694,y=0.23,zoneID=210}},coords={x=0.694,y=0.23,source="quest_giver",zoneID=210},questType="standard"},
[13654] = {id=13654,name="There's Something About the Squire",level=25,requiredLevel=25,faction="both",expansion=2,zoneID=2817,mapID=118,description="Every day, the Black Knight's squire, Maloric, makes a big show of heading to Crystalsong Forest with his axe over his shoulder. He wants us to believe he's chopping wood, but he never returns with more than a few twigs. He usually goes toward the ruins southwest of the Mirror of Twilight. He spends a lot of time out there, even for a squire with responsibilities to his knight. Find a way to distract or incapacitate him and search him. If he's up to something, we'll know it.",objectivesText="Obtain a Large Femur from a Skeletal Woodcutter and use it to incapacitate Maloric. Search Maloric for evidence, then report back to Crusader Rhydalla at the Argent Tournament Grounds. Progress: Did the squire's behavior yield any clues?",starts={{npcID=33417,x=0.694,y=0.23,zoneID=210}},ends={{npcID=33417,x=0.694,y=0.23,zoneID=210}},coords={x=0.694,y=0.23,source="quest_giver",zoneID=210},questType="standard"},
[13662] = {id=13662,name="Gaining Acceptance",level=15,requiredLevel=15,faction="both",expansion=2,zoneID=51,mapID=32,objectivesText="Progress: You've worked your way up through the Brotherhood's corporate hierarchy, <race>. We have begun to look favorably upon you. Quite an accomplishment! If you're interested in more work and earning more respect amongst us, listen up. We can refine our fiery flux by adding a simple Dark Iron residue to the mix. This Dark Iron residue can be found in Blackrock Depths. Bring me all the Dark Iron residue you find!",starts={{mapID=32,npcID=14624,x=0.385,y=0.285}},ends={{mapID=32,npcID=14624,x=0.385,y=0.285}},coords={mapID=32,source="quest_giver",x=0.385,y=0.285},questType="dungeon"},
[13663] = {id=13663,name="The Black Knight's Orders",level=25,requiredLevel=25,faction="both",expansion=2,zoneID=210,mapID=118,description="We must discover who sent the Black Knight to the tournament and what his master hopes to gain by killing the competitors. The Kirin Tor has offered to help in this matter and provided us with something to help our search. Take this enchanted bridle to the Black Knight's camp on the eastern edge of the tournament grounds and use it to gain control over the Black Knight's gryphon . The bridle's magic will force the gryphon to take you to his master's home. Search it and return with anything you find.",objectivesText="Use the Enchanted Bridle to gain control of the Black Knight's Gryphon and ride it to its destination. Once you have arrived, recover the Stolen Tournament Invitation and the Black Knight's Orders and bring them to Crusader Rhydalla at the Argent Tournament Grounds. Progress: What did you discover?",starts={{npcID=33417,x=0.694,y=0.23,zoneID=210}},ends={{npcID=33417,x=0.694,y=0.23,zoneID=210}},coords={x=0.694,y=0.23,source="quest_giver",zoneID=210},questType="standard"},
[13664] = {id=13664,name="The Black Knight's Fall",level=25,requiredLevel=25,faction="both",expansion=2,zoneID=210,mapID=118,description="We must put an end to the Black Knight 's scheming, and show those who oppose us that we will not stand by and allow our champions to be murdered. By now, he will suspect that someone is on his trail. Challenge him in the light of day, where he cannot refuse or murder in the dark, . Use my argent charger for the battle. It's housed in the stables. Speak to Squire Cavin at the Ring of Champions. The squire will call the Black Knight to battle, but you will make him answer for his crimes.",objectivesText="Defeat the Black Knight and then speak to Crusader Rhydalla at the Argent Tournament Grounds.",starts={{npcID=33417,x=0.694,y=0.23,zoneID=210}},ends={{npcID=33417,x=0.694,y=0.23,zoneID=210}},coords={x=0.694,y=0.23,source="quest_giver",zoneID=210},questType="standard"},
[13665] = {id=13665,name="The Grand Melee",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="The grand melee is the most important of the tournament's competitions. The people of Stormwind adore their knights and are looking forward to seeing us win the melee. To that end, they've been honing their skills against the other valiants. I suggest you do the same. Go to the stables outside the pavilion, equip your lance, mount the stabled Elwynn steed, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.",objectivesText="Bring 3 Marks of the Valiant to Captain Joseph Holley at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion. Progress: Have you completed your training for the grand melee?",starts={{npcID=33223,x=0.766,y=0.192,zoneID=210}},ends={{npcID=33223,x=0.766,y=0.192,zoneID=210}},coords={x=0.766,y=0.192,source="quest_giver",zoneID=210},questType="standard"},
[13666] = {id=13666,name="A Blade Fit For A Champion",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, . Otherwise, you'll catch warts.",objectivesText="Retrieve the Ashwood Brand and bring it to Arcanist Taelis at the Argent Tournament Grounds. Progress: Were you able to recover the blade?",starts={{npcID=33625,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33625,x=0.764,y=0.194,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13667] = {id=13667,name="The Argent Tournament",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy. Arcanist Taelis is the Silver Covenant's representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Alliance tent in the northeastern part of the grounds.",objectivesText="Speak with Arcanist Taelis at the Argent Tournament grounds to enroll in the tournament.",starts={{npcID=33817,x=0.696,y=0.228,zoneID=210}},ends={{npcID=33625,x=0.764,y=0.194,zoneID=210}},coords={x=0.696,y=0.228,source="quest_giver",zoneID=210},questType="standard"},
[13668] = {id=13668,name="The Argent Tournament",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy. Magister Edien Sunhollow is the Sunreaver representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Horde tent in the southeastern part of the grounds.",objectivesText="Speak with Magister Edien Sunhollow at the Argent Tournament grounds to enroll in the tournament.",starts={{npcID=33817,x=0.696,y=0.228,zoneID=210}},ends={{npcID=33542,x=0.762,y=0.242,zoneID=210}},coords={x=0.696,y=0.228,source="quest_giver",zoneID=210},questType="standard"},
[13669] = {id=13669,name="A Worthy Weapon",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Our champions have taken a liking to ancient weapons produced here in Northrend. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.",objectivesText="Bring the Blade of Drak'Mar to Arcanist Taelis at the Argent Tournament Grounds. Progress: Were the wandering bard's tales true? Have you brought a blade?",starts={{npcID=33625,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33625,x=0.764,y=0.194,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13670] = {id=13670,name="The Edge Of Winter",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=2817,mapID=118,description="The Ironforge grand champion's squire told me an intriguing story. In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, .",objectivesText="Arcanist Taelis at the Argent Tournament Grounds wants you to bring him Winter's Edge . Progress: Did you win the blade?",starts={{npcID=33625,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33625,x=0.764,y=0.194,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13671] = {id=13671,name="Training In The Field",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=65,mapID=118,description="The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament. Travel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.",objectivesText="Avareth Swiftstrike at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment. Progress: Have you tested yourself in combat against the Scourge?",starts={{npcID=33646,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33646,x=0.764,y=0.194,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13672] = {id=13672,name="Up To The Challenge",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant. When you are ready to begin the challenge, return to me.",objectivesText="Present Arcanist Taelis at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge. Progress: Do you wish to take the aspirant's challenge?",starts={{npcID=33625,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33625,x=0.764,y=0.194,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13673] = {id=13673,name="A Blade Fit For A Champion",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, . Otherwise, you'll catch warts.",objectivesText="Retrieve the Ashwood Brand and bring it to Magister Edien Sunhollow at the Argent Tournament Grounds. Progress: Were you able to recover the blade?",starts={{npcID=33542,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33542,x=0.762,y=0.242,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13674] = {id=13674,name="A Worthy Weapon",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="Our champions have taken a liking to ancient weapons produced here in Northrend. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.",objectivesText="Bring the Blade of Drak'Mar to Magister Edien Sunhollow at the Argent Tournament Grounds. Progress: Were the wandering bard's tales true? Have you brought a blade?",starts={{npcID=33542,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33542,x=0.762,y=0.242,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13675] = {id=13675,name="The Edge Of Winter",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=2817,mapID=118,description="I heard an interesting story from one of the Orgrimmar valiants. In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, .",objectivesText="Magister Edien Sunhollow at the Argent Tournament Grounds wants you to bring him Winter's Edge . Progress: Did you win the blade?",starts={{npcID=33542,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33542,x=0.762,y=0.242,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13676] = {id=13676,name="Training In The Field",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=65,mapID=118,description="The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament. Travel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.",objectivesText="Amariel Sunsworn at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment. Progress: Have you tested yourself in combat against the Scourge?",starts={{npcID=33658,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33658,x=0.762,y=0.242,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13677] = {id=13677,name="Learning The Reins",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds. Visit the stables outside the pavilion, equip your lance, and mount up on the Sunreaver hawkstrider. Familiarize yourself with the mount and use its abilities to defeat the three different kinds of training dummies.",objectivesText="Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets, and then return to Galathia Brightdawn at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or the Sunreaver Pavilion. Progress: How goes the mounted combat practice?",starts={{npcID=33659,x=0.762,y=0.244,zoneID=210}},ends={{npcID=33659,x=0.762,y=0.244,zoneID=210}},coords={x=0.762,y=0.244,source="quest_giver",zoneID=210},questType="standard"},
[13678] = {id=13678,name="Up To The Challenge",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant. When you are ready to begin the challenge, return to me.",objectivesText="Present Magister Edien Sunhollow at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge. Progress: Do you wish to take the aspirant's challenge?",starts={{npcID=33542,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33542,x=0.762,y=0.242,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13679] = {id=13679,name="The Aspirant's Challenge",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You have trained hard as an aspirant, , and now the time has come to test your mounted combat skills against a skilled opponent. Equip your lance, then go to the stables outside the pavilion and mount up on the stabled Quel'dorei steed. At the Aspirants' Ring on the northern side of the tournament grounds, you'll find Squire David. He'll make certain that you're ready for the fight and call out your opponent. Good luck, . May your horse be steady and your aim true.",objectivesText="Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Arcanist Taelis at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.",starts={{npcID=33625,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33625,x=0.764,y=0.194,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13680] = {id=13680,name="The Aspirant's Challenge",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="You have trained hard as an aspirant, , and now the time has come to test your mounted combat skills against an experienced opponent. Equip your lance, then go to the stables outside the pavilion and mount the Sunreaver hawkstrider. At the Aspirants' Ring on the northern side of the tournament grounds, you'll find a human child called Squire David. He'll ask if you're ready for the fight and call out your opponent. Good luck, . May your mount be steady and your aim true.",objectivesText="Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Magister Edien Sunhollow at the Argent Tournament Grounds.",starts={{npcID=33542,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33542,x=0.762,y=0.242,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13681] = {id=13681,name="A Chip Off the Ulduar Block",level=25,requiredLevel=25,faction="none",expansion=2,description="Getting stone for this job has been a nightmare, I tell ya! There are tons of stone available from ruins in safe places, but those holier-than-thou paladins won't go for it. Something about 'priceless artifacts.' Anyway, whining about that isn't going to get this place built. There are tons of crumbling titan ruins in the Foot Steppes and at the Inventor's Library in Storm Peaks. Take my, uh, 'chisel' with you and see if you can break those huge blocks into useful pieces.",objectivesText="Bring 15 Small Stone Blocks to Bozzle Blastbolt at the Argent Tournament Grounds.",starts={{x=0.74,y=0.246,mapID=118,npcID=33435}},ends={{x=0.74,y=0.246,mapID=118,npcID=33435}},coords={mapID=118,x=0.74,y=0.246},questType="standard"},
[13682] = {id=13682,name="Threat From Above",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated. Our skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.",objectivesText="Eadric the Pure at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers .",starts={{npcID=33759,x=0.698,y=0.234,zoneID=210}},ends={{npcID=33759,x=0.698,y=0.234,zoneID=210}},coords={x=0.698,y=0.234,source="quest_giver",zoneID=210},questType="group"},
[13684] = {id=13684,name="A Valiant Of Stormwind",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You've proven yourself worthy of competing under the banner of Stormwind, . Now, you should introduce yourself to Marshal Jacob Alerius , who leads the Stormwind delegation. As Stormwind's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, , and I wish you luck in the competition ahead.",objectivesText="Speak with Marshal Jacob Alerius at the Argent Tournament Grounds to become a valiant of Stormwind.",starts={{npcID=33625,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33225,x=0.766,y=0.192,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13685] = {id=13685,name="A Valiant Of Ironforge",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You've proven yourself worthy of competing under the banner of Ironforge, . Now, you should introduce yourself to Lana Stouthammer , who leads the Ironforge delegation. As Ironforge's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, , and I wish you luck in the competition ahead.",objectivesText="Speak with Lana Stouthammer at the Argent Tournament Grounds to become a valiant of Ironforge.",starts={{npcID=33625,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33312,x=0.766,y=0.194,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13688] = {id=13688,name="A Valiant Of Gnomeregan",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You've proven yourself worthy of competing under the banner of Gnomeregan, . Now, you should introduce yourself to Ambrose Boltspark , who leads the Gnomeregan delegation. As the gnomish grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, , and I wish you luck in the competition ahead.",objectivesText="Speak with Ambrose Boltspark at the Argent Tournament Grounds to become a valiant of Gnomeregan.",starts={{npcID=33625,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33335,x=0.764,y=0.198,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13689] = {id=13689,name="A Valiant Of Darnassus",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You've proven yourself worthy of competing under the banner of Darnassus, . Now, you should introduce yourself to Jaelyne Evensong , who leads the Darnassus delegation. As the night elf grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, , and I wish you luck in the competition ahead.",objectivesText="Speak with Jaelyne Evensong at the Argent Tournament Grounds to become a valiant of Darnassus.",starts={{npcID=33625,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33592,x=0.762,y=0.19,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13690] = {id=13690,name="A Valiant Of The Exodar",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You've proven yourself worthy of competing under the banner of the Exodar, . Now, you should introduce yourself to Colosos , who leads the Exodar delegation. As the draenei grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, , and I wish you luck in the competition ahead.",objectivesText="Speak with Colosos at the Argent Tournament Grounds to become a valiant of the Exodar.",starts={{npcID=33625,x=0.764,y=0.194,zoneID=210}},ends={{npcID=33593,x=0.76,y=0.192,zoneID=210}},coords={x=0.764,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13691] = {id=13691,name="A Valiant Of Orgrimmar",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="You've proven yourself worthy of competing under the banner of Orgrimmar, . Now, you should speak with Mokra the Skullcrusher , who leads Orgrimmar's competitors. As Orgrimmar's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, , and I wish you luck in the competition ahead.",objectivesText="Speak with Mokra the Skullcrusher at the Argent Tournament Grounds to become a valiant of Orgrimmar.",starts={{npcID=33542,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33361,x=0.764,y=0.244,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13693] = {id=13693,name="A Valiant Of Sen'jin",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="You've proven yourself worthy of competing under the banner of Sen'jin, . Now, you should speak with Zul'tore who leads Sen'jin's warriors. As the troll grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, , and I wish you luck in the competition ahead.",objectivesText="Speak with Zul'tore at the Argent Tournament Grounds to become a valiant of Sen'jin.",starts={{npcID=33542,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33372,x=0.76,y=0.244,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13694] = {id=13694,name="A Valiant Of Thunder Bluff",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="You've proven yourself worthy of competing under the banner of Thunder Bluff, . Now, you should speak with Runok Wildmane , who leads Thunder Bluff's competitors. As Thunder Bluff's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, , and I wish you luck in the competition ahead.",objectivesText="Speak with Runok Wildmane at the Argent Tournament Grounds to become a valiant of Thunder Bluff.",starts={{npcID=33542,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33403,x=0.762,y=0.246,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13695] = {id=13695,name="A Valiant Of Undercity",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="You've proven yourself worthy of competing under the banner of the Undercity, . Now, you should speak with Deathstalker Visceri , who leads the Undercity delegation. As grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, , and I wish you luck in the competition ahead.",objectivesText="Speak with Deathstalker Visceri at the Argent Tournament Grounds to become a valiant of the Undercity.",starts={{npcID=33542,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33373,x=0.764,y=0.242,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13696] = {id=13696,name="A Valiant Of Silvermoon",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="You've proven yourself worthy of competing under the banner of Silvermoon, . Now, you should speak with Eressea Dawnsinger , who leads the Silvermoon delegation. As Silvermoon's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, , and I wish you luck in the competition ahead.",objectivesText="Speak with Eressea Dawnsinger at the Argent Tournament Grounds to become a valiant of Silvermoon.",starts={{npcID=33542,x=0.762,y=0.242,zoneID=210}},ends={{npcID=33379,x=0.764,y=0.238,zoneID=210}},coords={x=0.762,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13697] = {id=13697,name="The Valiant's Charge",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents. The valiants are a spirited lot, competing amongst themselves for honor and notoriety. Train as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.",objectivesText="Bring 25 Valiant's Seals to Mokra the Skullcrusher at the Argent Tournament Grounds. Progress: Are you ready to demonstrate your mastery of the valiant's skills?",starts={{npcID=33361,x=0.764,y=0.244,zoneID=210}},ends={{npcID=33361,x=0.764,y=0.244,zoneID=210}},coords={x=0.764,y=0.244,source="quest_giver",zoneID=210},questType="standard"},
[13699] = {id=13699,name="The Valiant's Challenge",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You are nearly ready to compete on behalf of Stormwind in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade. Go to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready. After the battle is concluded, we will speak of the outcome.",objectivesText="Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Marshal Jacob Alerius at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion. Progress: Have you overcome the Argent champion?",starts={{npcID=33225,x=0.766,y=0.192,zoneID=210}},ends={{npcID=33225,x=0.766,y=0.192,zoneID=210}},coords={x=0.766,y=0.192,source="quest_giver",zoneID=210},questType="standard"},
[13702] = {id=13702,name="A Champion Rises",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Congratulations, . You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities. Justicar Mariel Trueheart has asked to speak with you, , and to formally enter you in the champions' grand melee.",objectivesText="Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.",starts={{npcID=33225,x=0.766,y=0.192,zoneID=210}},ends={{npcID=33817,x=0.696,y=0.228,zoneID=210}},coords={x=0.766,y=0.192,source="quest_giver",zoneID=210},questType="standard"},
[13703] = {id=13703,name="Valiant Of Ironforge",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Ironforge's tournament delegation? You will train and rise through the ranks as you have before, but when you are named a champion of Ironforge, your squire will have the option of carrying our banner into battle.",objectivesText="Speak with Lana Stouthammer again if you wish to become a valiant of Ironforge.",starts={{npcID=33312,x=0.766,y=0.194,zoneID=210}},ends={{npcID=33312,x=0.766,y=0.194,zoneID=210}},coords={x=0.766,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13704] = {id=13704,name="Valiant Of Gnomeregan",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Welcome, champion. Word of your combat prowess has already reached my ears. Gnomeregan's delegation could really benefit from a like you. You will train and rise through the ranks as you have before, but when you are named a champion of Gnomeregan, your squire will have the option of carrying our banner into battle.",objectivesText="Speak with Ambrose Boltspark again if you wish to become a valiant of Gnomeregan.",starts={{npcID=33335,x=0.764,y=0.198,zoneID=210}},ends={{npcID=33335,x=0.764,y=0.198,zoneID=210}},coords={x=0.764,y=0.198,source="quest_giver",zoneID=210},questType="standard"},
[13705] = {id=13705,name="Valiant Of The Exodar",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Welcome, champion. Word of your deeds has already reached my ears. Do you wish to join the Exodar's tournament delegation? You will train and rise through the ranks as you have before, but when you are named a champion of the Exodar, your squire will have the option of carrying our banner into battle.",objectivesText="Speak with Colosos again if you wish to become a valiant of the Exodar.",starts={{npcID=33593,x=0.76,y=0.192,zoneID=210}},ends={{npcID=33593,x=0.76,y=0.192,zoneID=210}},coords={x=0.76,y=0.192,source="quest_giver",zoneID=210},questType="standard"},
[13706] = {id=13706,name="Valiant Of Darnassus",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Welcome, champion. I have heard of your accomplishments and we would be honored if you would join the delegation from Darnassus. You will train and rise through the ranks as you have before, but when you are named a champion of Darnassus, your squire will have the option of carrying our banner into battle.",objectivesText="Speak with Jaelyne Eveonsong again if you wish to become a valiant of Darnassus.",starts={{npcID=33592,x=0.762,y=0.19,zoneID=210}},ends={{npcID=33592,x=0.762,y=0.19,zoneID=210}},coords={x=0.762,y=0.19,source="quest_giver",zoneID=210},questType="standard"},
[13707] = {id=13707,name="Valiant Of Orgrimmar",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Orgrimmar's delegation. You will train and rise through the ranks as you have before, but when you are named a champion of Orgrimmar, your gruntling will have the option of carrying our banner into battle.",objectivesText="Speak with Mokra the Skullcrusher again if you wish to become a valiant of Orgrimmar.",starts={{npcID=33361,x=0.764,y=0.244,zoneID=210}},ends={{npcID=33361,x=0.764,y=0.244,zoneID=210}},coords={x=0.764,y=0.244,source="quest_giver",zoneID=210},questType="standard"},
[13708] = {id=13708,name="Valiant Of Sen'jin",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="Greetings, champion. If you are willing, I would welcome you into Sen'jin's tournament delegation. You will train and rise through the ranks as you have before, but when you are named a champion of Sen'jin, your gruntling will have the option of carrying our banner into battle.",objectivesText="Speak with Zul'tore again if you wish to become a valiant of Sen'jin.",starts={{npcID=33372,x=0.76,y=0.244,zoneID=210}},ends={{npcID=33372,x=0.76,y=0.244,zoneID=210}},coords={x=0.76,y=0.244,source="quest_giver",zoneID=210},questType="standard"},
[13709] = {id=13709,name="Valiant Of Thunder Bluff",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="Welcome, champion. As grand champion of the Thunder Bluff delegation, I would be honored to welcome you into our ranks, if you are willing. You will train and rise through the ranks as you have before, but when you are named a champion of Thunder Bluff, your gruntling will have the option of carrying our banner into battle.",objectivesText="Speak with Runok Wildmane again if you wish to become a valiant of Thunder Bluff.",starts={{npcID=33403,x=0.762,y=0.246,zoneID=210}},ends={{npcID=33403,x=0.762,y=0.246,zoneID=210}},coords={x=0.762,y=0.246,source="quest_giver",zoneID=210},questType="standard"},
[13710] = {id=13710,name="Valiant Of Undercity",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="Welcome, champion. The Forsaken delegation could always use more s like you. Would you join us? You will train and rise through the ranks as you have before, but when you are named a champion of the Undecity, your gruntling will have the option of carrying our banner into battle.",objectivesText="Speak with Deathstalker Visceri again if you wish to become a valiant of the Undercity.",starts={{npcID=33373,x=0.764,y=0.242,zoneID=210}},ends={{npcID=33373,x=0.764,y=0.242,zoneID=210}},coords={x=0.764,y=0.242,source="quest_giver",zoneID=210},questType="standard"},
[13711] = {id=13711,name="Valiant Of Silvermoon",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Silvermoon's delegation. You will train and rise through the ranks as you have before, but when you are named a champion of Silvermoon, your gruntling will have the option of carrying our banner into battle.",objectivesText="Speak with Eressea Dawnsinger again if you wish to become a valiant of Silvermoon.",starts={{npcID=33379,x=0.764,y=0.238,zoneID=210}},ends={{npcID=33379,x=0.764,y=0.238,zoneID=210}},coords={x=0.764,y=0.238,source="quest_giver",zoneID=210},questType="standard"},
[13713] = {id=13713,name="The Valiant's Challenge",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You are nearly ready to compete on behalf of Ironforge in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade. Go to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready. After the battle is concluded, we will speak of the outcome.",objectivesText="Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Lana Stouthammer at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion. Progress: Have you overcome the Argent champion?",starts={{npcID=33312,x=0.766,y=0.194,zoneID=210}},ends={{npcID=33312,x=0.766,y=0.194,zoneID=210}},coords={x=0.766,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
[13714] = {id=13714,name="The Valiant's Charge",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents. The valiants are a spirited lot, competing amongst themselves for honor and notoriety. Train as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.",objectivesText="Bring 25 Valiant's Seals to Lana Stouthammer at the Argent Tournament Grounds. Progress: Are you ready to demonstrate your mastery of the valiant's skills?",starts={{npcID=33312,x=0.766,y=0.194,zoneID=210}},ends={{npcID=33312,x=0.766,y=0.194,zoneID=210}},coords={x=0.766,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
