[13723] = {id=13723,name="The Valiant's Challenge",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You are nearly ready to compete on behalf of Gnomeregan in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade. Go to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready. After the battle is concluded, we will speak of the outcome.",objectivesText="Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Ambrose Boltspark at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.",starts={{npcID=33335,x=0.764,y=0.198,zoneID=210}},ends={{npcID=33335,x=0.764,y=0.198,zoneID=210}},coords={x=0.764,y=0.198,source="quest_giver",zoneID=210},questType="standard"},
[13724] = {id=13724,name="The Valiant's Challenge",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You are nearly ready to compete on behalf of the Exodar in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade. Go to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready. After the battle is concluded, we will speak of the outcome.",objectivesText="Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Colosos at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.",starts={{npcID=33593,x=0.76,y=0.192,zoneID=210}},ends={{npcID=33593,x=0.76,y=0.192,zoneID=210}},coords={x=0.76,y=0.192,source="quest_giver",zoneID=210},questType="standard"},
[13725] = {id=13725,name="The Valiant's Challenge",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="You are nearly ready to compete on behalf of Darnassus in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade. Go to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready. After the battle is concluded, we will speak of the outcome.",objectivesText="Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Jaelyne Evensong at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.",starts={{npcID=33592,x=0.762,y=0.19,zoneID=210}},ends={{npcID=33592,x=0.762,y=0.19,zoneID=210}},coords={x=0.762,y=0.19,source="quest_giver",zoneID=210},questType="standard"},
[13726] = {id=13726,name="The Valiant's Challenge",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade. Go to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready. After the battle is concluded, we will speak of the outcome.",objectivesText="Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Mokra the Skullcrusher at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.",starts={{npcID=33361,x=0.764,y=0.244,zoneID=210}},ends={{npcID=33361,x=0.764,y=0.244,zoneID=210}},coords={x=0.764,y=0.244,source="quest_giver",zoneID=210},questType="standard"},
