[13732] = {id=13732,name="A Champion Rises",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Congratulations, . You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities. Justicar Mariel Trueheart has asked to speak with you, , and to formally enter you in the grand melee.",objectivesText="Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.",starts={{npcID=33312,x=0.766,y=0.194,zoneID=210}},ends={{npcID=33817,x=0.696,y=0.228,zoneID=210}},coords={x=0.766,y=0.194,source="quest_giver",zoneID=210},questType="standard"},
