[13854] = {id=13854,name="At The Enemy's Gates",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel. In the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions. Do not fear the masses of boneguard footmen, , for they can easily be trampled under your horse's hooves.",objectivesText="Ranii at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts , and 3 Boneguard Lieutenants .",starts={{npcID=33656,x=0.76,y=0.19,zoneID=210}},ends={{npcID=33656,x=0.76,y=0.19,zoneID=210}},coords={x=0.76,y=0.19,source="quest_giver",zoneID=210},questType="standard"},
[13855] = {id=13855,name="At The Enemy's Gates",level=25,requiredLevel=25,faction="alliance",expansion=2,zoneID=210,mapID=118,description="Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel. In the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions. Do not fear the masses of boneguard footmen, , for they can easily be trampled under your horse's hooves.",objectivesText="Airae Starseeker at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts , and 3 Boneguard Lieutenants . Progress: Have served alongside the crusaders in the Court of Bones?",starts={{npcID=33654,x=0.764,y=0.19,zoneID=210}},ends={{npcID=33654,x=0.764,y=0.19,zoneID=210}},coords={x=0.764,y=0.19,source="quest_giver",zoneID=210},questType="standard"},
[13856] = {id=13856,name="At The Enemy's Gates",level=25,requiredLevel=25,faction="horde",expansion=2,zoneID=210,mapID=118,description="Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel. In the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions. Do not fear the masses of boneguard footmen, , for they can easily be trampled under your horse's hooves.",objectivesText="Morah Worgsister at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts , and 3 Boneguard Lieutenants .",starts={{npcID=33544,x=0.764,y=0.244,zoneID=210}},ends={{npcID=33544,x=0.764,y=0.244,zoneID=210}},coords={x=0.764,y=0.244,source="quest_giver",zoneID=210},questType="standard"},
