[24912] = {id=24912,name="Empowerment",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4812,objectivesText="Progress: < Highlord Darion Mograine speaks to you purposefully.> Shadow's Edge is prepared to receive its final endowment of power. The time has come to attempt the forging of Shadowmourne!",starts={{npcID=37120}},questType="raid"},
[24914] = {id=24914,name="Personal Property",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4812,mapID=118,description="You can detect no hinges or openings on this box. Were it not for the shifting of items inside, it could easily be mistaken for solid metal. If anyone could know the method of its opening, it would be Highlord Mograine.",objectivesText="Bring the Sealed Chest to Highlord Darion Mograine in Icecrown Citadel. Provided item:",questType="standard"},
[24915] = {id=24915,name="Mograine's Reunion",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4812,mapID=118,objectivesText="Progress: What is that you hold, <class>? It calls out to me, stirring feelings I thought to be long dead.",questType="raid"},
[24916] = {id=24916,name="Jaina's Locket",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4812,mapID=118,objectivesText="Progress: Yes, <class>? How can I assist you?",questType="raid"},
