[26012] = {id=26012,name="Trouble at Wyrmrest",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=65,mapID=115,description="My old friend Krasus sends word of dire happenings at Wyrmrest, in Dragonblight. His missive was brief, but it seems that there has been some sort of attack on the Ruby Sanctum beneath the Temple. Pressing business here in Dalaran keeps me from attending to the matter personally, but I have heard word of your exploits in the Lich King's Citadel and you are doubtless up to the task -- perhaps you could assist Krasus in my stead?",objectivesText="Speak with Krasus at Wyrmrest Temple in Dragonblight.",starts={{x=0.306,y=0.486,mapID=125,npcID=16128}},ends={{npcID=27990,x=0.598,y=0.546,zoneID=65}},coords={mapID=115,source="quest_giver",x=0.598,y=0.545},questType="raid"},
[26013] = {id=26013,name="Assault on the Sanctum",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=4987,mapID=115,description=", something terrible has transpired within the Ruby Sanctum beneath the Temple. The entry to the Sanctum is in ruins, and its guardians violently slain. We sent scouts to investigate, but they have not returned. I cannot help but fear the worst. Enter the Ruby Sanctum and discover what has befallen the home of my flight. Once we have more information, we can plan our next steps accordingly.",objectivesText="Investigate the Ruby Sanctum beneath Wyrmrest Temple.",starts={{npcID=27990,x=0.598,y=0.546,zoneID=65}},ends={{npcID=40429,zoneID=4987}},coords={x=0.598,y=0.546,source="quest_giver",zoneID=65},questType="raid"},
[26034] = {id=26034,name="The Twilight Destroyer",level=30,requiredLevel=30,faction="both",expansion=2,zoneID=65,mapID=115,description="This was no reckless attack, but rather a carefully orchestrated strike against the heart of the Red Dragonflight. Zarithrian, on the bluff over there, is overseeing the assault, but the true leader of this force is a brash and powerful Twilight dragon named Halion . Not since Dargonax has a full-grown spawn of Sinestra's twisted experiments been seen. Slay him, , and then when the invasion has been fully repelled, report to Krasus regarding all you have seen here.",objectivesText="Defeat Halion and repel the invasion of the Ruby Sanctum .",starts={{npcID=40429,zoneID=4987}},ends={{npcID=27990,x=0.598,y=0.546,zoneID=65}},coords={mapID=115,source="quest_giver",x=0.598,y=0.545},questType="raid"},
[28649] = {id=28649,name="A Special Surprise",level=8,requiredLevel=8,faction="alliance",expansion=2,zoneID=4298,mapID=124,description="We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, . Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing. I was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty worgen in there that I think you'll take great pleasure in executing.",starts={{npcID=29053,x=0.528,y=0.814,mapID=124}},ends={{npcID=29053,x=0.528,y=0.814,mapID=124}},coords={x=0.528,y=0.814,source="quest_giver",mapID=124},questType="standard"},
}
end)
